function fitZoom(box, azDeg, elDeg, frac) {
  const az = THREE.MathUtils.degToRad(azDeg), el = THREE.MathUtils.degToRad(elDeg);
  const dir = new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el)).normalize();
  const right = new THREE.Vector3().crossVectors(YAX, dir).normalize();
  const up = new THREE.Vector3().crossVectors(dir, right).normalize();
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  const p = new THREE.Vector3();
  for (let i = 0; i < 8; i++) {
    p.set(i & 1 ? box.max.x : box.min.x, i & 2 ? box.max.y : box.min.y, i & 4 ? box.max.z : box.min.z);
    const sx = p.dot(right), sy = p.dot(up);
    minX = Math.min(minX, sx); maxX = Math.max(maxX, sx);
    minY = Math.min(minY, sy); maxY = Math.max(maxY, sy);
  }
  const A = Math.max(0.2, (canvas.clientWidth || 800) / (canvas.clientHeight || 600));
  const zH = (2 * 3 * frac) / Math.max(1e-6, maxY - minY);
  const zW = (2 * 3 * A * frac) / Math.max(1e-6, maxX - minX);
  return Math.min(zH, zW);
}

