      } else { A.head.visible = A.shaft.visible = false; }
    });
    rayGeo.attributes.position.needsUpdate = true;

    const cp = connGeo.attributes.position.array;
    const src = [[cx - RX, -RY], [cx + RX, -RY], [cx - RX, RY], [cx + RX, RY]];
    const dst = [[-RX * S, PCY - RY * S], [RX * S, PCY - RY * S], [-RX * S, PCY + RY * S], [RX * S, PCY + RY * S]];
    for (let i = 0; i < 4; i++) {
      cp[i * 6] = src[i][0]; cp[i * 6 + 1] = src[i][1]; cp[i * 6 + 2] = 0;
      cp[i * 6 + 3] = dst[i][0]; cp[i * 6 + 4] = dst[i][1]; cp[i * 6 + 5] = 0;
    }
    connGeo.attributes.position.needsUpdate = true;
  }
}

function setTx(v, stopPlay) {
  state.tx = Math.max(0, Math.min(4, v));
  if (stopPlay) { state.playing = false; btnPlay.textContent = '▶ Play lateral translation'; btnPlay.classList.remove('active'); }
  slider.value = state.tx;
  txVal.textContent = state.tx.toFixed(2);
  refresh();
}

function setMode(m) {
  state.mode = m;
  const flow = (m === 'flow');
  flowGroup.visible = flow;
  matBlack.opacity = flow ? 0.15 : 1;
  matRed.opacity = flow ? 0.15 : 1;
  matActive.opacity = flow ? 0.9 : 1;
  pathLine.material.opacity = flow ? 0.25 : 0.95;
  axisLine.visible = !flow;
  btnMode3d.classList.toggle('active', !flow);
  btnModeFlow.classList.toggle('active', flow);
  L3.forEach(l => l.div.style.visibility = flow ? 'hidden' : 'visible');
  LF.forEach(l => l.div.style.visibility = flow ? 'visible' : 'hidden');
  refresh();
  applyView();
}

/* ---------- controls ---------------------------------------------------- */
const btnPlay = document.getElementById('btnPlay');
const btnMode3d = document.getElementById('btnMode3d');
const btnModeFlow = document.getElementById('btnModeFlow');

btnPlay.addEventListener('click', () => {
  state.playing = !state.playing;
  tween = null;
  btnPlay.textContent = state.playing ? '❚❚ Pause' : '▶ Play lateral translation';
  btnPlay.classList.toggle('active', state.playing);
});
slider.addEventListener('input', () => { tween = null; setTx(parseFloat(slider.value), true); });
btnMode3d.addEventListener('click', () => setMode('3d'));
btnModeFlow.addEventListener('click', () => setMode('flow'));

/* ---------- demo steps -------------------------------------------------- */
const STEPS = [
  { title: 'The strip of cameras', mode: '3d', tx: 0,
    text: 'Five copies of the same camera stand in a row, each frustum aimed away from you while thick red arrows push rightward along the base. The pose never rotates — only the position slides sideways.' },
  { title: 'Slide it sideways', mode: '3d', tx: 2,
    text: 'The highlighted camera translates along the baseline with zero forward component, exactly like a scene sliding past the side window of a moving car.' },
  { title: 'What the image sees', mode: 'flow', tx: 2,
    text: 'In the projected view every scene point drifts laterally in the image, and all flow vectors point the same way — opposite the camera motion.' },
  { title: 'Depth-dependent parallax', mode: 'flow', tx: 4,
    text: 'At maximum displacement the near points\' flow vectors stretch far more than the distant ones, since the image shift is f·t_x/Z. Lateral translation is what makes depth visible.' }
];
let stepIdx = 0, tween = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepIdx').textContent = 'Step ' + (stepIdx + 1) + '/' + STEPS.length;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  state.playing = false;
  btnPlay.textContent = '▶ Play lateral translation';
  btnPlay.classList.remove('active');
  if (s.mode !== state.mode) setMode(s.mode);
  tween = { a: state.tx, b: s.tx, e: 0, dur: 0.8 };
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ---------- animation loop --------------------------------------------- */
let _last = performance.now();
function loop(now) {
  requestAnimationFrame(loop);
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  if (tween) {
    tween.e += dt;
    const k = Math.min(1, tween.e / tween.dur), s = k * k * (3 - 2 * k);
    setTx(tween.a + (tween.b - tween.a) * s);
    if (k >= 1) tween = null;
  } else if (state.playing) {
    let v = state.tx + dt * 0.75;
    if (v > 4) v = 0;
    setTx(v);
  }
}
requestAnimationFrame(loop);

/* ---------- boot -------------------------------------------------------- */
setMode('3d');
setTx(0);
applyView();
goToStep(0);
document.getElementById('btnReset').style.display = '';

let _viewRT = null;
new ResizeObserver(() => {
  clearTimeout(_viewRT);
  _viewRT = setTimeout(() => { if (!_userMovedCamera) applyView(); }, 90);
}).observe(canvas);
// @FIGURE_CODE_END

