// @FIGURE_CODE_BEGIN
/* ---------------- element spec ----------------------------------------
   frustum edge          → CylinderGeometry tube r=0.016, black 0x000000 (10 per camera:
                           4 rectangle edges + 4 apex edges + 2 face diagonals)
   projection centre     → SphereGeometry(0.062) black, at (0,0,0.6) — apex toward viewer,
                           so it projects BELOW the rectangle in the figure view
   image rectangle       → x∈[-0.5,0.5], y∈[-0.1,0.35], z=0
   red arrow             → BoxGeometry shaft 1.05×0.12×0.12 + ConeGeometry(0.16,0.45), 0xFF0000,
                           lying on the projection-centre line (y=0, z=0.6)
   baseline trace        → Line + LineDashedMaterial red (only while camera is moving)
   active camera         → same frustum group in orange 0xE86A00 + dashed optical axis (−Z)
   near scene points     → SphereGeometry(0.10) blue 0x1F6FEB at z = −2.5
   far scene points      → SphereGeometry(0.10) grey 0x888888 at z = −8
   projection rays       → LineSegments (vertex colours) apex → scene point
   image-plane hits      → SphereGeometry(0.032) on the active camera's rectangle
   magnified panel       → PlaneGeometry(4.5,2.03) white + 4 black border tubes
   panel dots / ghosts   → SphereGeometry(0.085 / 0.065)
   flow arrows           → Box shaft + Cone head, point-coloured, pointing −X
------------------------------------------------------------------------ */

const COL = { black: 0x000000, red: 0xff0000, near: 0x1f6feb, far: 0x888888, active: 0xe86a00 };

const matBlack  = new THREE.MeshBasicMaterial({ color: COL.black,  transparent: true, opacity: 1 });
const matRed    = new THREE.MeshBasicMaterial({ color: COL.red,    transparent: true, opacity: 1 });
const matActive = new THREE.MeshBasicMaterial({ color: COL.active, transparent: true, opacity: 1 });
const matNear   = new THREE.MeshBasicMaterial({ color: COL.near });
const matFar    = new THREE.MeshBasicMaterial({ color: COL.far });
const matNearG  = new THREE.MeshBasicMaterial({ color: COL.near, transparent: true, opacity: 0.30 });
const matFarG   = new THREE.MeshBasicMaterial({ color: COL.far,  transparent: true, opacity: 0.30 });
const matBorder = new THREE.MeshBasicMaterial({ color: 0x000000 });

const YAX = new THREE.Vector3(0, 1, 0);
function tube(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8, 1), mat);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(YAX, dir.clone().normalize());
  return m;
}

/* ---------- state (declared early: applyView reads it) ------------------ */
const state = { tx: 0, mode: '3d', playing: false, ann: true };

/* ---------- one camera frustum (true 3-D object) ------------------------ */
const RX = 0.5, YB = -0.1, YT = 0.35, F = 0.6;
const YC = (YB + YT) / 2;                       // rectangle centre height = principal point

function makeFrustum(mat, r) {
  const g = new THREE.Group();
  const TL = new THREE.Vector3(-RX, YT, 0), TR = new THREE.Vector3(RX, YT, 0);
  const BR = new THREE.Vector3(RX, YB, 0), BL = new THREE.Vector3(-RX, YB, 0);
  const A = new THREE.Vector3(0, 0, F);
  const segs = [[TL, TR], [TR, BR], [BR, BL], [BL, TL],
                [A, TL], [A, TR], [A, BR], [A, BL],
                [TL, BR], [TR, BL]];
  for (const [a, b] of segs) g.add(tube(a, b, r, mat));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.062, 18, 12), mat);
  dot.position.copy(A);
  g.add(dot);
  g.userData.dot = dot;
  return g;
}

/* ---------- red arrow --------------------------------------------------- */
function makeArrow(mat) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.12, 0.12), mat);
  shaft.position.x = -0.225;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.45, 20), mat);
  head.rotation.z = -Math.PI / 2;
  head.position.x = 0.525;
  g.add(shaft, head);
  return g;
}

/* ---------- the filmstrip ----------------------------------------------- */
const strip = new THREE.Group();
scene.add(strip);

const CAM_X = [-4.8, -2.4, 0.0, 2.4, 4.8];
CAM_X.forEach((x, i) => {
  const f = makeFrustum(matBlack, 0.016);
  f.position.x = x;
  strip.add(f);
  registerInteractive(f, {
    title: 'Wireframe camera ' + (i + 1) + ' of 5',
    tooltip: 'Identical camera, identical orientation',
    body: 'All five copies are the same camera. The black dot is the projection centre (pinhole); the rectangle above it is the image plane, f = 0.6 in front of the centre. Only the x position changes along the strip — the optical axis still points away from you along −Z, so the motion is perpendicular to the line of sight.'
  });
});

[-6.4, -3.6, -1.2, 1.2, 3.6, 6.2].forEach((x) => {
  const a = makeArrow(matRed);
  a.position.set(x, 0, F);
  strip.add(a);
  registerInteractive(a, {
    title: 'Translation direction (+x)',
    tooltip: 'Motion parallel to the image plane',
    body: 'The red arrows give the camera velocity: purely sideways, lying in the image plane. Because it is perpendicular to the viewing direction the forward (Z) component is exactly zero — like a scene sliding past the side window of a moving car.'
  });
});

/* ---------- active (moving) camera + its track -------------------------- */
const activeGroup = new THREE.Group();
const activeCam = makeFrustum(matActive, 0.021);
activeGroup.add(activeCam);
const axisLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, F), new THREE.Vector3(0, YC, -1.6)]),
  new THREE.LineDashedMaterial({ color: COL.active, dashSize: 0.13, gapSize: 0.1 })
);
axisLine.computeLineDistances();
activeGroup.add(axisLine);
scene.add(activeGroup);
registerInteractive(activeCam.userData.dot, {
  title: 'Projection centre (optical centre)',
  tooltip: 'The pinhole — every ray passes through here',
  body: 'Every scene ray crosses this point on its way to the image plane a distance f = 0.6 in front of it. Translating this point sideways by t_x shifts the image of a point at depth Z by Δu = −f·t_x/Z.'
});

const pathLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-4.8, 0, F), new THREE.Vector3(4.8, 0, F)]),
  new THREE.LineDashedMaterial({ color: 0xff5555, dashSize: 0.17, gapSize: 0.13, transparent: true, opacity: 0.9 })
);
pathLine.computeLineDistances();
scene.add(pathLine);

/* ---------- scene points, rays, magnified image panel ------------------- */
const flowGroup = new THREE.Group();
flowGroup.visible = false;
scene.add(flowGroup);

const CX0 = -4.8;
const PTS = [];
function addScenePoint(u0, v, z, isNear) {
  const D = F - z;                         // depth in front of the projection centre
  const X = CX0 + u0 * D / F;
  const Y = v * D / F;
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.10, 14, 10), isNear ? matNear : matFar);
  m.position.set(X, Y, z);
  flowGroup.add(m);
  PTS.push({ p: m.position, D, u0, v, near: isNear, col: new THREE.Color(isNear ? COL.near : COL.far) });
}
[[0.10, 0.05], [0.19, 0.22], [0.27, -0.03], [0.35, 0.28], [0.42, 0.12], [0.47, 0.19]]
  .forEach(([u, v]) => addScenePoint(u, v, -2.5, true));
[[-0.16, 0.10], [-0.08, 0.02], [0.00, 0.14], [0.08, 0.06], [0.15, 0.12], [0.20, 0.00]]
  .forEach(([u, v]) => addScenePoint(u, v, -8.0, false));

const N = PTS.length;
const rayGeo = new THREE.BufferGeometry();
rayGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(N * 6), 3));
const rayCol = new Float32Array(N * 6);
PTS.forEach((pt, i) => {
  for (let k = 0; k < 2; k++) {
    rayCol[i * 6 + k * 3] = pt.col.r; rayCol[i * 6 + k * 3 + 1] = pt.col.g; rayCol[i * 6 + k * 3 + 2] = pt.col.b;
  }
});
rayGeo.setAttribute('color', new THREE.BufferAttribute(rayCol, 3));
const rays = new THREE.LineSegments(rayGeo,
  new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.55 }));
flowGroup.add(rays);
registerInteractive(rays, {
  title: 'Projection rays',
  tooltip: 'Scene point → projection centre → image',
  body: 'Each ray runs from a scene point through the projection centre and pierces the image plane. As the centre slides sideways the rays swing, and the pierce points sweep across the image.'
});

const hitDots = PTS.map(pt => {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.032, 10, 8), pt.near ? matNear : matFar);
  flowGroup.add(m);
  return m;
});

