  <div style="display:flex;gap:4px;align-items:center">
    <button id="btnPrev">◀</button>
    <button id="btnNext">▶</button>
    <span id="stepIdx" style="color:#555"></span>
  </div>
  <div id="stepTitle" style="font-weight:700;margin-top:5px"></div>
  <div id="stepText" style="line-height:1.38;color:#333"></div>
</div>

<div style="border-top:1px solid #dcdfe3;margin-top:6px;padding-top:6px;color:#555;line-height:1.35">
  Image shift of a point at depth Z: &Delta;u = &minus;f&middot;t<sub>x</sub>/Z &nbsp;(f = 0.6).<br>
  Drag to orbit, scroll to zoom, hover parts for hints.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
/* ---------------- element spec ----------------------------------------
   frustum edge          → CylinderGeometry tube r=0.016, black 0x000000 (10 per camera:
                           4 rectangle edges + 4 apex edges + 2 face diagonals)
   projection centre     → SphereGeometry(0.062) black, at (0,0,0.6) — apex toward viewer,
                           so it projects BELOW the rectangle in the figure view
   image rectangle       → x∈[-0.5,0.5], y∈[-0.1,0.35], z=0
   red arrow             → BoxGeometry shaft 1.05×0.12×0.12 + ConeGeometry(0.16,0.45), 0xFF0000,
                           lying on the projection-centre line (y=0, z=0.6)
   baseline trace        → Line + LineDashedMaterial red (only while camera is moving)
   active camera         → same frustum group in orange 0xE86A00 + dashed optical axis (−Z)
   near scene points     → SphereGeometry(0.10) blue 0x1F6FEB at z = −2.5
   far scene points      → SphereGeometry(0.10) grey 0x888888 at z = −8
   projection rays       → LineSegments (vertex colours) apex → scene point
   image-plane hits      → SphereGeometry(0.032) on the active camera's rectangle
   magnified panel       → PlaneGeometry(4.5,2.03) white + 4 black border tubes
   panel dots / ghosts   → SphereGeometry(0.085 / 0.065)
   flow arrows           → Box shaft + Cone head, point-coloured, pointing −X
------------------------------------------------------------------------ */

const COL = { black: 0x000000, red: 0xff0000, near: 0x1f6feb, far: 0x888888, active: 0xe86a00 };

const matBlack  = new THREE.MeshBasicMaterial({ color: COL.black,  transparent: true, opacity: 1 });
const matRed    = new THREE.MeshBasicMaterial({ color: COL.red,    transparent: true, opacity: 1 });
const matActive = new THREE.MeshBasicMaterial({ color: COL.active, transparent: true, opacity: 1 });
const matNear   = new THREE.MeshBasicMaterial({ color: COL.near });
const matFar    = new THREE.MeshBasicMaterial({ color: COL.far });
const matNearG  = new THREE.MeshBasicMaterial({ color: COL.near, transparent: true, opacity: 0.30 });
const matFarG   = new THREE.MeshBasicMaterial({ color: COL.far,  transparent: true, opacity: 0.30 });
const matBorder = new THREE.MeshBasicMaterial({ color: 0x000000 });

const YAX = new THREE.Vector3(0, 1, 0);
function tube(a, b, r, mat) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const m = new THREE.Mesh(new THREE.CylinderGeometry(r, r, len, 8, 1), mat);
  m.position.copy(a).addScaledVector(dir, 0.5);
  m.quaternion.setFromUnitVectors(YAX, dir.clone().normalize());
  return m;
}

/* ---------- state (declared early: applyView reads it) ------------------ */
const state = { tx: 0, mode: '3d', playing: false, ann: true };

/* ---------- one camera frustum (true 3-D object) ------------------------ */
const RX = 0.5, YB = -0.1, YT = 0.35, F = 0.6;
const YC = (YB + YT) / 2;                       // rectangle centre height = principal point

function makeFrustum(mat, r) {
  const g = new THREE.Group();
  const TL = new THREE.Vector3(-RX, YT, 0), TR = new THREE.Vector3(RX, YT, 0);
  const BR = new THREE.Vector3(RX, YB, 0), BL = new THREE.Vector3(-RX, YB, 0);
  const A = new THREE.Vector3(0, 0, F);
  const segs = [[TL, TR], [TR, BR], [BR, BL], [BL, TL],
                [A, TL], [A, TR], [A, BR], [A, BL],
                [TL, BR], [TR, BL]];
  for (const [a, b] of segs) g.add(tube(a, b, r, mat));
  const dot = new THREE.Mesh(new THREE.SphereGeometry(0.062, 18, 12), mat);
  dot.position.copy(A);
  g.add(dot);
  g.userData.dot = dot;
  return g;
}

/* ---------- red arrow --------------------------------------------------- */
function makeArrow(mat) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.12, 0.12), mat);
  shaft.position.x = -0.225;
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.45, 20), mat);
  head.rotation.z = -Math.PI / 2;
  head.position.x = 0.525;
  g.add(shaft, head);
  return g;
}

/* ---------- the filmstrip ----------------------------------------------- */
const strip = new THREE.Group();
scene.add(strip);

const CAM_X = [-4.8, -2.4, 0.0, 2.4, 4.8];
CAM_X.forEach((x, i) => {
  const f = makeFrustum(matBlack, 0.016);
  f.position.x = x;
  strip.add(f);
  registerInteractive(f, {
    title: 'Wireframe camera ' + (i + 1) + ' of 5',
    tooltip: 'Identical camera, identical orientation',
    body: 'All five copies are the same camera. The black dot is the projection centre (pinhole); the rectangle above it is the image plane, f = 0.6 in front of the centre. Only the x position changes along the strip — the optical axis still points away from you along −Z, so the motion is perpendicular to the line of sight.'
  });
});

[-6.4, -3.6, -1.2, 1.2, 3.6, 6.2].forEach((x) => {
  const a = makeArrow(matRed);
  a.position.set(x, 0, F);
  strip.add(a);
  registerInteractive(a, {
    title: 'Translation direction (+x)',
    tooltip: 'Motion parallel to the image plane',
    body: 'The red arrows give the camera velocity: purely sideways, lying in the image plane. Because it is perpendicular to the viewing direction the forward (Z) component is exactly zero — like a scene sliding past the side window of a moving car.'
  });
});

/* ---------- active (moving) camera + its track -------------------------- */
const activeGroup = new THREE.Group();
const activeCam = makeFrustum(matActive, 0.021);
activeGroup.add(activeCam);
const axisLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(0, 0, F), new THREE.Vector3(0, YC, -1.6)]),
  new THREE.LineDashedMaterial({ color: COL.active, dashSize: 0.13, gapSize: 0.1 })
);
axisLine.computeLineDistances();
activeGroup.add(axisLine);
scene.add(activeGroup);
registerInteractive(activeCam.userData.dot, {
  title: 'Projection centre (optical centre)',
  tooltip: 'The pinhole — every ray passes through here',
  body: 'Every scene ray crosses this point on its way to the image plane a distance f = 0.6 in front of it. Translating this point sideways by t_x shifts the image of a point at depth Z by Δu = −f·t_x/Z.'
});

const pathLine = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-4.8, 0, F), new THREE.Vector3(4.8, 0, F)]),
  new THREE.LineDashedMaterial({ color: 0xff5555, dashSize: 0.17, gapSize: 0.13, transparent: true, opacity: 0.9 })
);
pathLine.computeLineDistances();
scene.add(pathLine);

/* ---------- scene points, rays, magnified image panel ------------------- */
const flowGroup = new THREE.Group();
flowGroup.visible = false;
scene.add(flowGroup);

const CX0 = -4.8;
const PTS = [];
function addScenePoint(u0, v, z, isNear) {
  const D = F - z;                         // depth in front of the projection centre
  const X = CX0 + u0 * D / F;
  const Y = v * D / F;
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.10, 14, 10), isNear ? matNear : matFar);
  m.position.set(X, Y, z);
  flowGroup.add(m);
  PTS.push({ p: m.position, D, u0, v, near: isNear, col: new THREE.Color(isNear ? COL.near : COL.far) });
}
[[0.10, 0.05], [0.19, 0.22], [0.27, -0.03], [0.35, 0.28], [0.42, 0.12], [0.47, 0.19]]
  .forEach(([u, v]) => addScenePoint(u, v, -2.5, true));
[[-0.16, 0.10], [-0.08, 0.02], [0.00, 0.14], [0.08, 0.06], [0.15, 0.12], [0.20, 0.00]]
  .forEach(([u, v]) => addScenePoint(u, v, -8.0, false));

const N = PTS.length;
const rayGeo = new THREE.BufferGeometry();
rayGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(N * 6), 3));
const rayCol = new Float32Array(N * 6);
PTS.forEach((pt, i) => {
  for (let k = 0; k < 2; k++) {
    rayCol[i * 6 + k * 3] = pt.col.r; rayCol[i * 6 + k * 3 + 1] = pt.col.g; rayCol[i * 6 + k * 3 + 2] = pt.col.b;
  }
});
rayGeo.setAttribute('color', new THREE.BufferAttribute(rayCol, 3));
const rays = new THREE.LineSegments(rayGeo,
  new THREE.LineBasicMaterial({ vertexColors: true, transparent: true, opacity: 0.55 }));
flowGroup.add(rays);
registerInteractive(rays, {
  title: 'Projection rays',
  tooltip: 'Scene point → projection centre → image',
  body: 'Each ray runs from a scene point through the projection centre and pierces the image plane. As the centre slides sideways the rays swing, and the pierce points sweep across the image.'
});

const hitDots = PTS.map(pt => {
  const m = new THREE.Mesh(new THREE.SphereGeometry(0.032, 10, 8), pt.near ? matNear : matFar);
  flowGroup.add(m);
  return m;
});

/* magnified image plane panel */
const S = 4.5, PX = -3.5, PY = 3.8;
const panelFace = new THREE.Mesh(new THREE.PlaneGeometry(RX * 2 * S, (YT - YB) * S),
  new THREE.MeshBasicMaterial({ color: 0xffffff }));
panelFace.position.set(PX, PY, -0.02);
flowGroup.add(panelFace);
registerInteractive(panelFace, {
  title: 'Image plane (magnified ×4.5)',
  tooltip: 'What the moving camera records',
  body: 'The camera image blown up 4.5×. Faded dots mark where each scene point appeared at t_x = 0, solid dots where it appears now. The arrows between them are the optical-flow vectors: all parallel, all opposite the camera motion, and longer for near points than for far ones.'
});
{
  const hw = RX * S, hh = (YT - YB) * S / 2, b = 0.028;
  const c = [
    new THREE.Vector3(PX - hw, PY - hh, 0), new THREE.Vector3(PX + hw, PY - hh, 0),
    new THREE.Vector3(PX + hw, PY + hh, 0), new THREE.Vector3(PX - hw, PY + hh, 0)
  ];
  for (let i = 0; i < 4; i++) flowGroup.add(tube(c[i], c[(i + 1) % 4], b, matBorder));
}

const panelDots = [], panelGhosts = [], flowArrows = [];
PTS.forEach(pt => {
  const d = new THREE.Mesh(new THREE.SphereGeometry(0.085, 12, 10), pt.near ? matNear : matFar);
  const g = new THREE.Mesh(new THREE.SphereGeometry(0.065, 12, 10), pt.near ? matNearG : matFarG);
  flowGroup.add(d, g);
  panelDots.push(d); panelGhosts.push(g);
  const mat = new THREE.MeshBasicMaterial({ color: pt.near ? COL.near : COL.far });
  const shaft = new THREE.Mesh(new THREE.BoxGeometry(1, 0.055, 0.02), mat);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.095, 0.24, 12), mat);
  head.rotation.z = Math.PI / 2;                      // points −X
  flowGroup.add(shaft, head);
  flowArrows.push({ shaft, head });
});

/* connectors: small image rectangle → magnified panel */
const connGeo = new THREE.BufferGeometry();
connGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(24), 3));
const connectors = new THREE.LineSegments(connGeo,
  new THREE.LineBasicMaterial({ color: 0x9aa0a6, transparent: true, opacity: 0.5 }));
flowGroup.add(connectors);

/* ---------- camera framing --------------------------------------------- */
function fitZoom(box, azDeg, elDeg, frac) {
  const az = THREE.MathUtils.degToRad(azDeg), el = THREE.MathUtils.degToRad(elDeg);
  const dir = new THREE.Vector3(Math.cos(az) * Math.cos(el), Math.sin(el), Math.sin(az) * Math.cos(el)).normalize();
  const right = new THREE.Vector3().crossVectors(YAX, dir).normalize();
  const up = new THREE.Vector3().crossVectors(dir, right).normalize();
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  const p = new THREE.Vector3();
  for (let i = 0; i < 8; i++) {
    p.set(i & 1 ? box.max.x : box.min.x, i & 2 ? box.max.y : box.min.y, i & 4 ? box.max.z : box.min.z);
    const sx = p.dot(right), sy = p.dot(up);
    minX = Math.min(minX, sx); maxX = Math.max(maxX, sx);
    minY = Math.min(minY, sy); maxY = Math.max(maxY, sy);
  }
  const A = Math.max(0.2, (canvas.clientWidth || 900) / (canvas.clientHeight || 650));
  const zH = (2 * 3 * frac) / Math.max(1e-6, maxY - minY);
  const zW = (2 * 3 * A * frac) / Math.max(1e-6, maxX - minX);
  return Math.min(zH, zW);
}

/* Figure pose: azimuth 90° puts the strip exactly horizontal on screen (world +X
   → screen right, world +Z → straight down), a modest elevation drops each apex
   below its rectangle — the source's flat filmstrip composition.               */
const AZ3 = 90, EL3 = 30;
const AZF = 90, ELF = 6;
const BOX_3D   = new THREE.Box3(new THREE.Vector3(-7.25, -0.18, -0.05), new THREE.Vector3(7.05, 0.42, 0.72));
const BOX_FLOW = new THREE.Box3(new THREE.Vector3(-7.5, -0.45, -8.2), new THREE.Vector3(-0.2, 5.0, 0.72));

function applyView() {
  if (state.mode === 'flow') {
    setCameraView({
      projection: 'orthographic', azimuthDeg: AZF, elevationDeg: ELF,
      zoom: fitZoom(BOX_FLOW, AZF, ELF, 0.9), target: [-3.8, 2.2, -1.2], heightFraction: 0.9
    });
  } else {
    setCameraView({
      projection: 'orthographic', azimuthDeg: AZ3, elevationDeg: EL3,
      zoom: fitZoom(BOX_3D, AZ3, EL3, 0.95), target: [-0.1, 0.06, 0.3], heightFraction: 0.95
    });
  }
}

/* ---------- labels ------------------------------------------------------ */
const L3 = [], LF = [];
L3.push(addLabel('image plane', new THREE.Vector3(0, YT, 0), { color: '#333', fontSize: '11px', offset: [0, -13] }));
L3.push(addLabel('projection centre', new THREE.Vector3(0, 0, F), { color: '#333', fontSize: '11px', offset: [0, 24] }));
L3.push(addLabel('camera motion +x', new THREE.Vector3(-3.6, 0, F), { color: '#c00', fontSize: '11px', offset: [0, 24] }));

const lblTx = addLabel('t<sub>x</sub> = 0.00', new THREE.Vector3(CX0, YT, 0), { color: '#e86a00', bold: true, fontSize: '12px', offset: [0, -30] });

LF.push(addLabel('image plane &mdash; magnified &times;4.5', new THREE.Vector3(PX, PY + (YT - YB) * S / 2, 0), { color: '#111', bold: true, fontSize: '12px', offset: [0, -14] }));
LF.push(addLabel('&Delta;u = &minus;f&middot;t<sub>x</sub>/Z', new THREE.Vector3(PX - RX * S, PY - (YT - YB) * S / 2, 0), { color: '#444', fontSize: '11px', offset: [34, 14] }));
LF.push(addLabel('near points (Z &asymp; &minus;2.5) &mdash; long flow', new THREE.Vector3(-3.3, -0.3, -2.5), { color: '#1f6feb', fontSize: '11px', offset: [0, 12] }));
LF.push(addLabel('far points (Z &asymp; &minus;8) &mdash; short flow', new THREE.Vector3(-6.2, 1.8, -8.0), { color: '#666', fontSize: '11px', offset: [0, -10] }));
LF.push(addLabel('projection rays', new THREE.Vector3(-4.3, 0.35, -1.3), { color: '#777', fontSize: '11px', offset: [-6, 16] }));

/* ---------- update ------------------------------------------------------ */
const slider = document.getElementById('tx');
const txVal = document.getElementById('txVal');
const chkAnn = document.getElementById('chkAnn');

function activeVisible() {
  return state.mode === 'flow' || state.playing || state.tx > 0.001;
}

function updateVisibility() {
  const flow = state.mode === 'flow';
  const av = activeVisible();
  activeGroup.visible = av;
  axisLine.visible = av && state.ann;
  pathLine.visible = av;
  L3.forEach(l => l.div.style.visibility = (!flow && state.ann) ? 'visible' : 'hidden');
  lblTx.div.style.visibility = (!flow && av && state.ann) ? 'visible' : 'hidden';
  LF.forEach(l => l.div.style.visibility = (flow && state.ann) ? 'visible' : 'hidden');
}

const _a = new THREE.Vector3();
function refresh() {
  const cx = CX0 + state.tx;
  activeGroup.position.x = cx;
  lblTx.pos.set(cx, YT, 0);
  lblTx.div.innerHTML = 't<sub>x</sub> = ' + state.tx.toFixed(2);
  updateVisibility();

  if (state.mode === 'flow') {
    const rp = rayGeo.attributes.position.array;
    _a.set(cx, 0, F);
    PTS.forEach((pt, i) => {
      const u = F * (pt.p.x - cx) / pt.D;
      const v = pt.v;                               // unchanged by lateral motion
      const inside = Math.abs(u) <= RX && v >= YB && v <= YT;

      // ray (collapsed to zero length when the point has left the field of view)
      rp[i * 6] = _a.x; rp[i * 6 + 1] = _a.y; rp[i * 6 + 2] = _a.z;
      if (inside) { rp[i * 6 + 3] = pt.p.x; rp[i * 6 + 4] = pt.p.y; rp[i * 6 + 5] = pt.p.z; }
      else { rp[i * 6 + 3] = _a.x; rp[i * 6 + 4] = _a.y; rp[i * 6 + 5] = _a.z; }

      hitDots[i].visible = inside;
      hitDots[i].position.set(cx + u, v, 0.012);

      const yP = PY + (v - YC) * S;
      const x0 = PX + pt.u0 * S, x1 = PX + u * S;
      panelGhosts[i].position.set(x0, yP, 0.03);
      panelGhosts[i].visible = true;
      panelDots[i].visible = inside;
      panelDots[i].position.set(x1, yP, 0.05);

      const A = flowArrows[i], len = x0 - x1;
      if (inside && len > 0.30) {
        A.head.visible = A.shaft.visible = true;
        A.head.position.set(x1 + 0.12, yP, 0.04);
        A.shaft.scale.x = len - 0.24;
        A.shaft.position.set((x0 + x1 + 0.24) / 2, yP, 0.04);
      } else { A.head.visible = A.shaft.visible = false; }
    });
    rayGeo.attributes.position.needsUpdate = true;

    const cp = connGeo.attributes.position.array;
    const hw = RX * S, hh = (YT - YB) * S / 2;
    const src = [[cx - RX, YB], [cx + RX, YB], [cx - RX, YT], [cx + RX, YT]];
    const dst = [[PX - hw, PY - hh], [PX + hw, PY - hh], [PX - hw, PY + hh], [PX + hw, PY + hh]];
    for (let i = 0; i < 4; i++) {
      cp[i * 6] = src[i][0]; cp[i * 6 + 1] = src[i][1]; cp[i * 6 + 2] = 0;
      cp[i * 6 + 3] = dst[i][0]; cp[i * 6 + 4] = dst[i][1]; cp[i * 6 + 5] = 0;
    }
    connGeo.attributes.position.needsUpdate = true;
  }
}

function setTx(v, stopPlay) {
  state.tx = Math.max(0, Math.min(4, v));
  if (stopPlay) {
    state.playing = false;
    btnPlay.textContent = '▶ Play lateral translation';
    btnPlay.classList.remove('active');
  }
  slider.value = state.tx;
  txVal.textContent = state.tx.toFixed(2);
  refresh();
}

function setMode(m) {
  state.mode = m;
  const flow = (m === 'flow');
  flowGroup.visible = flow;
  matBlack.opacity = flow ? 0.13 : 1;
  matRed.opacity = flow ? 0.13 : 1;
  pathLine.material.opacity = flow ? 0.22 : 0.9;
  btnMode3d.classList.toggle('active', !flow);
  btnModeFlow.classList.toggle('active', flow);
  refresh();
  applyView();
}

/* ---------- controls ---------------------------------------------------- */
const btnPlay = document.getElementById('btnPlay');
const btnMode3d = document.getElementById('btnMode3d');
const btnModeFlow = document.getElementById('btnModeFlow');

btnPlay.addEventListener('click', () => {
  state.playing = !state.playing;
  tween = null;
  btnPlay.textContent = state.playing ? '❚❚ Pause' : '▶ Play lateral translation';
  btnPlay.classList.toggle('active', state.playing);
  refresh();
});
slider.addEventListener('input', () => { tween = null; setTx(parseFloat(slider.value), true); });
btnMode3d.addEventListener('click', () => setMode('3d'));
btnModeFlow.addEventListener('click', () => setMode('flow'));
chkAnn.addEventListener('change', () => { state.ann = chkAnn.checked; updateVisibility(); });

/* ---------- demo steps -------------------------------------------------- */
const STEPS = [
  { title: 'The strip of cameras', mode: '3d', tx: 0,
    text: 'Five copies of the same camera stand in a row, each frustum aimed away from you, with thick red arrows pushing rightward along the line of projection centres. The pose never rotates — only the position slides sideways.' },
  { title: 'Slide it sideways', mode: '3d', tx: 2,
    text: 'The highlighted camera translates along the baseline with zero forward component, exactly like a scene sliding past the side window of a moving car.' },
  { title: 'What the image sees', mode: 'flow', tx: 2,
    text: 'In the projected view every scene point drifts laterally in the image, and all flow vectors point the same way — opposite the camera motion.' },
  { title: 'Depth-dependent parallax', mode: 'flow', tx: 4,
    text: 'At maximum displacement the near points\' flow vectors stretch far more than the distant ones, since the image shift is f·t_x/Z. Lateral translation is what makes depth visible.' }
];
let stepIdx = 0, tween = null;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const s = STEPS[stepIdx];
  document.getElementById('stepIdx').textContent = 'Step ' + (stepIdx + 1) + '/' + STEPS.length;
  document.getElementById('stepTitle').textContent = s.title;
  document.getElementById('stepText').textContent = s.text;
  state.playing = false;
  btnPlay.textContent = '▶ Play lateral translation';
  btnPlay.classList.remove('active');
  if (s.mode !== state.mode) setMode(s.mode);
  tween = { a: state.tx, b: s.tx, e: 0, dur: 0.8 };
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));

/* ---------- animation loop --------------------------------------------- */
let _last = performance.now();
function loop(now) {
  requestAnimationFrame(loop);
  const dt = Math.min(0.05, (now - _last) / 1000); _last = now;
  if (tween) {
    tween.e += dt;
    const k = Math.min(1, tween.e / tween.dur), sm = k * k * (3 - 2 * k);
    setTx(tween.a + (tween.b - tween.a) * sm);
    if (k >= 1) tween = null;
  } else if (state.playing) {
    let v = state.tx + dt * 0.75;
    if (v > 4) v = 0;
    setTx(v);
  }
}
requestAnimationFrame(loop);

/* ---------- boot -------------------------------------------------------- */
setMode('3d');
setTx(0);
applyView();
goToStep(0);
setTx(0);
tween = null;
document.getElementById('btnReset').style.display = '';

let _viewRT = null;
new ResizeObserver(() => {
  clearTimeout(_viewRT);
  _viewRT = setTimeout(() => { if (!_userMovedCamera) applyView(); }, 90);
}).observe(canvas);
// @FIGURE_CODE_END

